declare
  v_id bigint;
  v_old_status text;
  v_created boolean := false;
  v_updated_at timestamptz;
begin
  if not private.current_user_is_pire_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_lesson_id is null or p_lesson_id <= 0
     or p_student_id is null or p_student_id <= 0
     or nullif(btrim(coalesce(p_status,'')),'') is null then
    raise exception 'invalid_attendance_input' using errcode = '22023';
  end if;

  if greatest(coalesce(p_late_minutes,0),0) > 1440 then
    raise exception 'invalid_late_minutes' using errcode = '22023';
  end if;

  if not exists(select 1 from public.pire_lessons l where l.id=p_lesson_id) then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;
  if not exists(select 1 from public.pire_students s where s.id=p_student_id) then
    raise exception 'student_not_found' using errcode = 'P0002';
  end if;

  if p_attendance_id is not null then
    select a.id,a.status into v_id,v_old_status
    from public.pire_attendance a
    where a.id=p_attendance_id
    for update;
    if not found then raise exception 'attendance_not_found' using errcode = 'P0002'; end if;
  else
    select a.id,a.status into v_id,v_old_status
    from public.pire_attendance a
    where a.lesson_id=p_lesson_id and a.student_id=p_student_id
    for update;
  end if;

  if v_id is null then
    insert into public.pire_attendance(
      lesson_id,student_id,status,late_minutes,absence_reason,parent_notified,entered_by,entered_at,updated_at
    ) values (
      p_lesson_id,p_student_id,btrim(p_status),greatest(coalesce(p_late_minutes,0),0),
      nullif(btrim(coalesce(p_absence_reason,'')),''),coalesce(p_parent_notified,false),
      nullif(btrim(coalesce(p_entered_by,'')),''),coalesce(p_entered_at,clock_timestamp()),clock_timestamp()
    ) returning id,public.pire_attendance.updated_at into v_id,v_updated_at;
    v_created := true;
  else
    update public.pire_attendance
    set lesson_id=p_lesson_id,
        student_id=p_student_id,
        status=btrim(p_status),
        late_minutes=greatest(coalesce(p_late_minutes,0),0),
        absence_reason=nullif(btrim(coalesce(p_absence_reason,'')),''),
        parent_notified=coalesce(p_parent_notified,false),
        entered_by=nullif(btrim(coalesce(p_entered_by,'')),''),
        entered_at=coalesce(p_entered_at,entered_at,clock_timestamp()),
        updated_at=clock_timestamp()
    where id=v_id
    returning public.pire_attendance.updated_at into v_updated_at;
  end if;

  if v_created or v_old_status is distinct from btrim(p_status) then
    insert into public.pire_attendance_history(
      attendance_id,lesson_id,student_id,old_status,new_status,package_change,changed_by,changed_at
    ) values (
      v_id,p_lesson_id,p_student_id,v_old_status,btrim(p_status),0,
      nullif(btrim(coalesce(p_entered_by,'')),''),clock_timestamp()
    );
  end if;

  return query select v_id,v_created,v_old_status,btrim(p_status),v_updated_at;
end;

declare
  v_payment_id bigint := p_payment_id;
  v_due numeric := 0;
  v_paid numeric := 0;
  v_status text := null;
  v_transaction_id bigint;
begin
  if not private.current_user_is_pire_admin() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  if p_student_id is null or p_student_id <= 0 or p_amount is null or p_amount <= 0 then
    raise exception 'invalid_payment_input' using errcode = '22023';
  end if;
  if not exists(select 1 from public.pire_students s where s.id = p_student_id) then
    raise exception 'student_not_found' using errcode = 'P0002';
  end if;

  if v_payment_id is not null then
    select amount_due, status into v_due, v_status
    from public.pire_payments
    where id = v_payment_id and student_id = p_student_id
    for update;
    if not found then raise exception 'payment_not_found' using errcode = 'P0002'; end if;
  elsif p_billing_month is not null then
    select id, amount_due, status into v_payment_id, v_due, v_status
    from public.pire_payments
    where student_id = p_student_id and billing_month = date_trunc('month',p_billing_month)::date
    order by id desc limit 1
    for update;
    if not found then
      insert into public.pire_payments(student_id,billing_month,amount_due,status,paid_at)
      values(p_student_id,date_trunc('month',p_billing_month)::date,greatest(coalesce(p_amount_due,p_amount),0),'Bekliyor',null)
      returning id, amount_due, status into v_payment_id, v_due, v_status;
    end if;
  end if;

  insert into public.pire_payment_transactions(payment_id,student_id,amount,payment_date,method,notes)
  values(v_payment_id,p_student_id,round(p_amount::numeric,2),coalesce(p_payment_date,current_date),nullif(btrim(p_method),''),nullif(btrim(p_notes),''))
  returning id into v_transaction_id;

  if v_payment_id is not null then
    select coalesce(sum(amount),0) into v_paid from public.pire_payment_transactions where payment_id = v_payment_id;
    if v_paid >= v_due and v_due > 0 then
      update public.pire_payments set status='Ödendi', paid_at=coalesce(paid_at,clock_timestamp()), updated_at=clock_timestamp() where id=v_payment_id;
      v_status := 'Ödendi';
    else
      update public.pire_payments set updated_at=clock_timestamp() where id=v_payment_id;
    end if;
  end if;

  return query select v_transaction_id, v_payment_id, v_status;
end;

declare
  v_request public.pire_student_registrations%rowtype;
  v_student public.pire_students%rowtype;
  v_course public.pire_courses%rowtype;
  v_teacher public.pire_teachers%rowtype;
  v_lesson_id bigint;
  v_package_id bigint;
  v_hash text;
  v_create_lesson boolean;
  v_create_package boolean;
  v_start time;
  v_end time;
  v_total integer;
begin
  if auth.uid() is null or not private.current_user_is_pire_admin() then
    raise exception 'admin_required' using errcode='42501';
  end if;
  if p_request_id is null or jsonb_typeof(p_student) is distinct from 'object'
    or jsonb_typeof(p_plan) is distinct from 'object' then
    raise exception 'invalid_registration' using errcode='22023';
  end if;

  -- Serialize retries for the same user/operation; no global student lock.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||p_request_id::text,0));
  v_hash:=pg_catalog.md5(p_student::text||'|'||p_plan::text);
  select * into v_request from public.pire_student_registrations
  where created_by=auth.uid() and request_id=p_request_id;
  if found then
    if v_request.request_hash<>v_hash then
      raise exception 'registration_request_conflict' using errcode='22023';
    end if;
    select * into strict v_student from public.pire_students where id=v_request.student_id;
    return jsonb_build_object('student',to_jsonb(v_student),'lesson_id',v_request.lesson_id,'package_id',v_request.package_id,'replayed',true);
  end if;

  if nullif(btrim(p_student->>'full_name'),'') is null
    or jsonb_typeof(p_plan->'createLesson') is distinct from 'boolean'
    or jsonb_typeof(p_plan->'createPackage') is distinct from 'boolean' then
    raise exception 'invalid_registration' using errcode='22023';
  end if;
  v_create_lesson:=(p_plan->>'createLesson')::boolean;
  v_create_package:=(p_plan->>'createPackage')::boolean;
  select * into v_course from public.pire_courses
  where lower(btrim(name))=lower(btrim(p_plan->>'course')) and status='Aktif'
  order by id limit 1;
  if not found then raise exception 'registration_course_not_found' using errcode='22023'; end if;

  if v_create_lesson then
    select * into v_teacher from public.pire_teachers
    where lower(btrim(full_name))=lower(btrim(p_plan->>'teacher')) and status='Aktif'
    order by id limit 1;
    if not found then raise exception 'registration_teacher_not_found' using errcode='22023'; end if;
    v_start:=(p_plan->>'startTime')::time;
    v_end:=(p_plan->>'endTime')::time;
    if v_start is null or v_end is null or v_end<=v_start
      or nullif(btrim(p_plan->>'room'),'') is null or (p_plan->>'lessonDate')::date is null then
      raise exception 'invalid_registration_lesson' using errcode='22023';
    end if;
  end if;
  if v_create_package then
    v_total:=(p_plan->>'totalLessons')::integer;
    if v_total is null or v_total<1 or v_total>100000
      or (p_plan->>'packageStart')::date is null or (p_plan->>'packageEnd')::date is null
      or (p_plan->>'packageEnd')::date<(p_plan->>'packageStart')::date then
      raise exception 'invalid_registration_package' using errcode='22023';
    end if;
  end if;

  insert into public.pire_students (
    full_name,birth_date,blood_group,phone,address,national_id,heard_from,registration_date,
    guardian_name,guardian_relation,guardian_phone,guardian_phone_2,guardian_national_id,
    emergency_contact,monthly_fee,payment_day,status,notes
  ) values (
    btrim(p_student->>'full_name'),(p_student->>'birth_date')::date,p_student->>'blood_group',
    p_student->>'phone',p_student->>'address',p_student->>'national_id',p_student->>'heard_from',
    coalesce((p_student->>'registration_date')::date,current_date),p_student->>'guardian_name',
    p_student->>'guardian_relation',p_student->>'guardian_phone',p_student->>'guardian_phone_2',
    p_student->>'guardian_national_id',p_student->>'emergency_contact',
    coalesce((p_student->>'monthly_fee')::numeric,0),coalesce((p_student->>'payment_day')::smallint,1),
    coalesce(p_student->>'status','Aktif'),p_student->>'notes'
  ) returning * into v_student;

  if v_create_lesson then
    insert into public.pire_lessons (
      course_id,course_name,teacher_id,teacher_name,lesson_type,lesson_date,start_time,end_time,
      duration_minutes,room,recurrence,pricing_type,status
    ) values (
      v_course.id,v_course.name,v_teacher.id,v_teacher.full_name,'Birebir ders',
      (p_plan->>'lessonDate')::date,v_start,v_end,
      (extract(epoch from (v_end-v_start))/60)::integer,p_plan->>'room',
      coalesce(p_plan->>'recurrence','Tek seferlik'),
      case when v_create_package then 'Ders paketi' else 'Ders başına' end,'Planlandı'
    ) returning id into v_lesson_id;
    insert into public.pire_lesson_students(lesson_id,student_id) values (v_lesson_id,v_student.id);
  end if;
  if v_create_package then
    insert into public.pire_packages (
      student_id,course_id,course_name,total_lessons,used_lessons,remaining_lessons,
      makeup_rights,frozen_lessons,start_date,end_date,status
    ) values (
      v_student.id,v_course.id,v_course.name,v_total,0,v_total,0,0,
      (p_plan->>'packageStart')::date,(p_plan->>'packageEnd')::date,'Aktif'
    ) returning id into v_package_id;
  end if;
  insert into public.pire_student_registrations(created_by,request_id,request_hash,student_id,lesson_id,package_id)
  values (auth.uid(),p_request_id,v_hash,v_student.id,v_lesson_id,v_package_id);
  return jsonb_build_object('student',to_jsonb(v_student),'lesson_id',v_lesson_id,'package_id',v_package_id,'replayed',false);
end;

declare
  v_student_id bigint;
begin
  if not private.current_user_is_pire_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if not exists (select 1 from public.pire_lessons l where l.id = p_lesson_id) then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_student_ids, array[]::bigint[])) s(id)
    left join public.pire_students st on st.id = s.id
    where st.id is null
  ) then
    raise exception 'student_not_found' using errcode = '23503';
  end if;

  delete from public.pire_lesson_students ls where ls.lesson_id = p_lesson_id;

  foreach v_student_id in array coalesce(p_student_ids, array[]::bigint[]) loop
    insert into public.pire_lesson_students(lesson_id, student_id)
    values (p_lesson_id, v_student_id)
    on conflict do nothing;

    lesson_id := p_lesson_id;
    student_id := v_student_id;
    return next;
  end loop;
end;

